);

// Cancel emergency
export const cancelEmergency = createAsyncThunk(
  'emergency/cancel',
  async (id: string, { rejectWithValue }) => {
    try {
      // TODO: Replace with actual API call
      // await api.put(`/emergency/${id}/cancel`);
      return id;
    } catch (error: any) {
