  }> => {
    await simulateDelay(500);
    
    // Calculate from mock data
    const completed = mockRequests.filter(r => r.status === 'completed');
    const avgTime = completed.reduce((sum, r) => sum + (r.estimatedTime || 0), 0) / (completed.length || 1);
    
