// PROFILE UPDATE
// ============================================
export type ProfileUpdateData = Partial<
  Pick<User, 'name' | 'phone' | 'avatar' | 'gender' | 'dateOfBirth' | 'address'>
>;

export type PatientUpdateData = ProfileUpdateData & {
  bloodGroup?: BloodGroup;
  height?: number;
  weight?: number;
