// src/store/slices/authSlice.ts
import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { 
  UserProfile, 
  AccountRole, 
  ProfileUpgrade, 
  DoctorProfile,
  HospitalProfile,
  BloodDonorProfile,
  PharmacyProfile 
} from '../types/auth';

interface AuthState {
  user: UserProfile | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  pendingRole: AccountRole | null;
  pendingUpgrades: ProfileUpgrade[];
}

const initialState: AuthState = {
  user: null,
  isAuthenticated: false,
  isLoading: false,
  pendingRole: null,
  pendingUpgrades: [],
};

const authSlice = createSlice({
  name: 'auth',
  initialState,
  reducers: {
    login: (state, action: PayloadAction<UserProfile>) => {
      state.user = action.payload;
      state.isAuthenticated = true;
      state.pendingRole = null;
    },
    logout: (state) => {
      state.user = null;
      state.isAuthenticated = false;
      state.pendingRole = null;
      state.pendingUpgrades = [];
    },
    setLoading: (state, action: PayloadAction<boolean>) => {
      state.isLoading = action.payload;
    },
    // Multi-role management
    addRole: (state, action: PayloadAction<AccountRole>) => {
      if (state.user && !state.user.roles.includes(action.payload)) {
        state.user.roles.push(action.payload);
      }
    },
    removeRole: (state, action: PayloadAction<AccountRole>) => {
      if (state.user) {
        state.user.roles = state.user.roles.filter(r => r !== action.payload);
      }
    },
    setPrimaryRole: (state, action: PayloadAction<AccountRole>) => {
      if (state.user) {
        state.user.primaryRole = action.payload;
      }
    },
    // Profile upgrades
    addUpgrade: (state, action: PayloadAction<ProfileUpgrade>) => {
      if (state.user && !state.user.upgrades.includes(action.payload)) {
        state.user.upgrades.push(action.payload);
      }
    },
    removeUpgrade: (state, action: PayloadAction<ProfileUpgrade>) => {
      if (state.user) {
        state.user.upgrades = state.user.upgrades.filter(u => u !== action.payload);
      }
    },
    // Admin approval
    setAdminApproved: (state, action: PayloadAction<boolean>) => {
      if (state.user) {
        state.user.isAdminApproved = action.payload;
      }
    },
    // Update profile with specific types
    updateDoctorProfile: (state, action: PayloadAction<Partial<DoctorProfile>>) => {
      if (state.user) {
        state.user = { ...state.user, ...action.payload };
      }
    },
    updateHospitalProfile: (state, action: PayloadAction<Partial<HospitalProfile>>) => {
      if (state.user) {
        state.user = { ...state.user, ...action.payload };
      }
    },
    updateBloodDonorProfile: (state, action: PayloadAction<Partial<BloodDonorProfile>>) => {
      if (state.user) {
        state.user = { ...state.user, ...action.payload };
      }
    },
    updatePharmacyProfile: (state, action: PayloadAction<Partial<PharmacyProfile>>) => {
      if (state.user) {
        state.user = { ...state.user, ...action.payload };
      }
    },
  },
});

export const {
  login,
  logout,
  setLoading,
  addRole,
  removeRole,
  setPrimaryRole,
  addUpgrade,
  removeUpgrade,
  setAdminApproved,
  updateDoctorProfile,
  updateHospitalProfile,
  updateBloodDonorProfile,
  updatePharmacyProfile,
} = authSlice.actions;

export default authSlice.reducer;

// src/store/slices/authSlice.ts
// AUTHENTICATION + MULTI-ROLE MANAGEMENT (No Data Save)

import { createSlice, PayloadAction, createAsyncThunk } from '@reduxjs/toolkit';

// ============================================
// TYPES
// ============================================

export type AccountRole = 'normal_user' | 'client' | 'doctor' | 'hospital' | 'hospital_admin' | 'hospital_authority' | 'pharmacy' | 'pharmacy_admin' | 'admin' | 'admin_applicant' | 'blood_donor' | 'emergency_volunteer';

export type ProfileUpgrade = 'client_patient' | 'blood_donor' | 'pharmacy_user' | 'emergency_volunteer';

export interface User {
  id: string;
  name?: string;
  fullName?: string;
  email: string;
  phone?: string;
  bloodGroup?: string;
  gender?: 'male' | 'female' | 'other';
  profileImage?: string;
  role?: AccountRole;
  
  // Multi-role support
  roles: AccountRole[];           // All roles user has
  primaryRole: AccountRole;       // Current active role
  upgrades: ProfileUpgrade[];     // Profile upgrades
  
  // Status
  isVerified?: boolean;
  isAdminApproved?: boolean;
  isActive?: boolean;
  isOnline?: boolean;
  
  // Timestamps
  createdAt: string;
  updatedAt?: string;
  lastLogin?: string;
  
  // ❌ Token সরানো হয়েছে - কোন ডাটা সেভ হবে না
  // token?: string;
  [key: string]: unknown;
}

export interface AuthState {
  user: User | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  error: string | null;
}

// ============================================
// INITIAL STATE
// ============================================

const initialState: AuthState = {
  user: null,
  isAuthenticated: false,
  isLoading: false,
  error: null,
};

// ============================================
// ASYNC THUNKS - localStorage সরানো হয়েছে
// ============================================

// ✅ Login thunk - কোন ডাটা সেভ করে না
export const loginUser = createAsyncThunk(
  'auth/loginUser',
  async ({ email, password }: { email: string; password: string }) => {
    // সিমুলেটেড API কল
    await new Promise(resolve => setTimeout(resolve, 1000));
    
    if (!email || !password) {
      throw new Error('Email and password required');
    }
    
    // টেম্পোরারি ইউজার - শুধু মেমোরিতে থাকবে
    const mockUser: User = {
      id: `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      name: email.split('@')[0],
      fullName: email.split('@')[0],
      email: email,
      role: 'client',
      roles: ['client', 'normal_user'],
      primaryRole: 'client',
      upgrades: [],
      isVerified: true,
      isActive: true,
      createdAt: new Date().toISOString(),
    };
    
    // ❌ localStorage.setItem সরানো হয়েছে
    return mockUser;
  }
);

// ✅ Register thunk - কোন ডাটা সেভ করে না
export const registerUser = createAsyncThunk(
  'auth/registerUser',
  async (userData: Partial<User> & { password: string }) => {
    await new Promise(resolve => setTimeout(resolve, 1000));
    
    const mockUser: User = {
      id: `session_${Date.now()}`,
      name: userData.name || userData.email?.split('@')[0] || 'User',
      email: userData.email || '',
      role: 'client',
      roles: ['client', 'normal_user'],
      primaryRole: 'client',
      upgrades: [],
      isVerified: true,
      isActive: true,
      createdAt: new Date().toISOString(),
    };
    
    // ❌ localStorage.setItem সরানো হয়েছে
    return mockUser;
  }
);

// ✅ Logout thunk - localStorage পরিষ্কার করার দরকার নেই
export const logoutUser = createAsyncThunk('auth/logoutUser', async () => {
  await new Promise(resolve => setTimeout(resolve, 500));
  // ❌ localStorage.removeItem সরানো হয়েছে
  return null;
});

// ❌ getCurrentUser সম্পূর্ণ সরিয়ে দেওয়া হয়েছে - কারণ কোন ডাটা সেভ নেই
// export const getCurrentUser = createAsyncThunk(...) - এই পুরো অংশ ডিলিট করুন

// ============================================
// SLICE
// ============================================

const authSlice = createSlice({
  name: 'auth',
  initialState,
  reducers: {
    loginStart: (state) => {
      state.isLoading = true;
      state.error = null;
    },
    loginSuccess: (state, action: PayloadAction<User>) => {
      state.isLoading = false;
      state.isAuthenticated = true;
      state.user = action.payload;
      state.error = null;
    },
    login: (state, action: PayloadAction<User>) => {
      state.isLoading = false;
      state.isAuthenticated = true;
      state.user = action.payload;
      state.error = null;
    },
    loginFailure: (state, action: PayloadAction<string>) => {
      state.isLoading = false;
      state.error = action.payload;
    },

    logout: (state) => {
      state.user = null;
      state.isAuthenticated = false;
      state.isLoading = false;
      state.error = null;
      // ❌ localStorage.removeItem('token'); সরানো হয়েছে
    },

    updateProfile: (state, action: PayloadAction<Partial<User>>) => {
      if (state.user) {
        state.user = { ...state.user, ...action.payload };
      }
    },
    
    // Multi-role management
    addRole: (state, action: PayloadAction<AccountRole>) => {
      if (state.user && !state.user.roles.includes(action.payload)) {
        state.user.roles.push(action.payload);
      }
    },
    removeRole: (state, action: PayloadAction<AccountRole>) => {
      if (state.user) {
        state.user.roles = state.user.roles.filter(r => r !== action.payload);
        if (state.user.primaryRole === action.payload) {
          state.user.primaryRole = state.user.roles[0] || 'normal_user';
        }
      }
    },
    setPrimaryRole: (state, action: PayloadAction<AccountRole>) => {
      if (state.user && state.user.roles.includes(action.payload)) {
        state.user.primaryRole = action.payload;
      }
    },
    addUpgrade: (state, action: PayloadAction<ProfileUpgrade>) => {
      if (state.user && !state.user.upgrades.includes(action.payload)) {
        state.user.upgrades.push(action.payload);
      }
    },
    removeUpgrade: (state, action: PayloadAction<ProfileUpgrade>) => {
      if (state.user) {
        state.user.upgrades = state.user.upgrades.filter(u => u !== action.payload);
      }
    },
    switchRole: (state, action: PayloadAction<AccountRole>) => {
      if (state.user && state.user.roles.includes(action.payload)) {
        state.user.primaryRole = action.payload;
      }
    },
    setOnlineStatus: (state, action: PayloadAction<boolean>) => {
      if (state.user) {
        state.user.isOnline = action.payload;
      }
    },
    clearError: (state) => {
      state.error = null;
    },
    setLoading: (state, action: PayloadAction<boolean>) => {
      state.isLoading = action.payload;
    },
  },
  
  extraReducers: (builder) => {
    builder
      // Login User
      .addCase(loginUser.pending, (state) => {
        state.isLoading = true;
        state.error = null;
      })
      .addCase(loginUser.fulfilled, (state, action) => {
        state.isLoading = false;
        state.isAuthenticated = true;
        state.user = action.payload;
        state.error = null;
      })
      .addCase(loginUser.rejected, (state, action) => {
        state.isLoading = false;
        state.error = action.error.message || 'Login failed';
      })
      // Register User
      .addCase(registerUser.pending, (state) => {
        state.isLoading = true;
        state.error = null;
      })
      .addCase(registerUser.fulfilled, (state, action) => {
        state.isLoading = false;
        state.isAuthenticated = true;
        state.user = action.payload;
        state.error = null;
      })
      .addCase(registerUser.rejected, (state, action) => {
        state.isLoading = false;
        state.error = action.error.message || 'Registration failed';
      })
      // Logout User
      .addCase(logoutUser.fulfilled, (state) => {
        state.user = null;
        state.isAuthenticated = false;
        state.isLoading = false;
        state.error = null;
      });
      // ❌ getCurrentUser এর কেসগুলি সরানো হয়েছে
  },
});

// ============================================
// SELECTORS
// ============================================

export const selectUser = (state: { auth: AuthState }) => state.auth.user;
export const selectIsAuthenticated = (state: { auth: AuthState }) => state.auth.isAuthenticated;
export const selectIsLoading = (state: { auth: AuthState }) => state.auth.isLoading;
export const selectAuthError = (state: { auth: AuthState }) => state.auth.error;
export const selectUserRoles = (state: { auth: AuthState }) => state.auth.user?.roles || [];
export const selectPrimaryRole = (state: { auth: AuthState }) => state.auth.user?.primaryRole || 'normal_user';
export const selectUserUpgrades = (state: { auth: AuthState }) => state.auth.user?.upgrades || [];

// ============================================
// EXPORTS
// ============================================

export const {
  loginStart,
  login,
  loginSuccess,
  loginFailure,
  logout,
  updateProfile,
  addRole,
  removeRole,
  setPrimaryRole,
  addUpgrade,
  removeUpgrade,
  switchRole,
  setOnlineStatus,
  clearError,
  setLoading,
} = authSlice.actions;

export default authSlice.reducer;

