      headers: this.getHeaders()
    });
    return response.json();
  }

  async triggerEmergencyAlert(type: string): Promise<void> {
    await fetch(`${API_BASE_URL}/women-care/emergency/alert`, {
      method: 'POST',
      headers: this.getHeaders(),
      body: JSON.stringify({ type })
    });
  }

  // Health Tips
  async getHealthTips(week: number): Promise<string[]> {
    const response = await fetch(`${API_BASE_URL}/women-care/health-tips?week=${week}`, {
      headers: this.getHeaders()
    });
    return response.json();
  }

  // Calculate due date
  calculateDueDate(lastMenstrualDate: string): string {
    const lmp = new Date(lastMenstrualDate);
    const dueDate = new Date(lmp);
    dueDate.setDate(dueDate.getDate() + 280); // 40 weeks
    return dueDate.toISOString().split('T')[0];
  }

  // Calculate current week
  calculateCurrentWeek(lastMenstrualDate: string): number {
    const lmp = new Date(lastMenstrualDate);
    const today = new Date();
    const diffTime = today.getTime() - lmp.getTime();
    const diffWeeks = Math.floor(diffTime / (1000 * 60 * 60 * 24 * 7));
    return Math.min(Math.max(diffWeeks, 1), 42);
  }

  // Predict next period
  predictNextPeriod(lastPeriodDate: string, cycleLength: number): string {
    const lastPeriod = new Date(lastPeriodDate);
    const nextPeriod = new Date(lastPeriod);
    nextPeriod.setDate(nextPeriod.getDate() + cycleLength);
    return nextPeriod.toISOString().split('T')[0];
  }

  // Predict ovulation
  predictOvulation(lastPeriodDate: string, cycleLength: number): string {
    const lastPeriod = new Date(lastPeriodDate);
    const ovulation = new Date(lastPeriod);
    ovulation.setDate(ovulation.getDate() + cycleLength - 14);
    return ovulation.toISOString().split('T')[0];
  }
}

export const womenCareService = new WomenCareService();

// src/services/authGuardService.ts
export class AuthGuardService {
  // Check if action requires login
  static requiresAuth(action: 'book_appointment' | 'order_medicine' | 'contact_doctor' | 'emergency_contact'): boolean {
    const actionsRequiringAuth = ['book_appointment', 'order_medicine', 'contact_doctor'];
    return actionsRequiringAuth.includes(action);
  }

  // Show login modal/prompt
  static showLoginPrompt(action: string, returnUrl: string) {
    // Store the intended action and return URL
    sessionStorage.setItem('intendedAction', action);
    sessionStorage.setItem('returnUrl', returnUrl);
    
    // Show toast notification
    const event = new CustomEvent('showLoginPrompt', {
      detail: {
        message: `Please login to ${action.replace('_', ' ')}`,
        action: action,
        returnUrl: returnUrl
      }
    });
    window.dispatchEvent(event);
    
    return false;
  }

  // Get intended action after login
  static getIntendedAction() {
    return {
      action: sessionStorage.getItem('intendedAction'),
      returnUrl: sessionStorage.getItem('returnUrl')
    };
  }

  // Clear intended action
  static clearIntendedAction() {
    sessionStorage.removeItem('intendedAction');
    sessionStorage.removeItem('returnUrl');
  }
}
